-- =============================================================================
-- SEED: Consumiveis (Pocoes, Pergaminhos, Bombas, Oleos, Ervas, Venenos, etc.)
-- Categoria: Consumiveis
-- Total de itens: 120
-- =============================================================================
-- Notas:
--   - categoria_id sera preenchido pelo script runner (busca 'Consumiveis' no DB)
--   - raridade_id: 1=Comum, 2=Incomum, 3=Raro, 4=Muito Raro, 5=Epico, 6=Lendario
--   - tipo[]: tag array para busca (poção, pergaminho, bomba, oleo, erva, veneno, alimento, kit)
--   - bonus: JSON com efeitos mecanicos
--   - cargas: numero de usos do item (NULL = uso unico)
--   - usos_por_dia: limite diario (NULL = sem limite)
-- =============================================================================

-- Inserir categoria se nao existir
INSERT INTO categorias_equipamento (nome, icone, ordem)
VALUES ('Consumíveis', 'flask', 13)
ON CONFLICT (nome) DO NOTHING;

-- Buscar ID da categoria (usado via variavel no script .cjs, aqui hardcoded para SQL puro)
-- Se rodar via psql, descomente:
-- \set cat_id (SELECT id FROM categorias_equipamento WHERE nome = 'Consumíveis')

INSERT INTO public.equipamentos (
  numero, nome, descricao, tipo, bonus, dano_base, elemento,
  requisitos, raridade_id, origem_lore, vinculo,
  categoria_id, propriedades, cargas, usos_por_dia,
  peso, preco_sugerido
) VALUES
-- ===================== POCOES DE CURA (1-10) =====================
  (400, 'Poção de Cura Menor', 'Restaura 2d4+2 pontos de vida ao ser consumida.', ARRAY['poção','cura']::text[], '{"cura":"2d4+2"}', NULL, ARRAY[]::text[], NULL, 1, 'Líquido vermelho brilhante com aroma de cereja. Receita universal conhecida por todos os alquimistas.', NULL, (SELECT id FROM categorias_equipamento WHERE nome = 'Consumíveis'), ARRAY['cura']::text[], NULL, NULL, 0.25, '50 PO'),
  (401, 'Poção de Cura', 'Restaura 4d4+4 pontos de vida ao ser consumida.', ARRAY['poção','cura']::text[], '{"cura":"4d4+4"}', NULL, ARRAY[]::text[], NULL, 2, 'Versão concentrada da poção de cura menor, preparada com essência de troll diluída.', NULL, (SELECT id FROM categorias_equipamento WHERE nome = 'Consumíveis'), ARRAY['cura']::text[], NULL, NULL, 0.25, '150 PO'),
  (402, 'Poção de Cura Maior', 'Restaura 8d4+8 pontos de vida ao ser consumida.', ARRAY['poção','cura']::text[], '{"cura":"8d4+8"}', NULL, ARRAY[]::text[], NULL, 3, 'Poção densa de cor rubi profundo, destilada com lágrimas de fênix.', NULL, (SELECT id FROM categorias_equipamento WHERE nome = 'Consumíveis'), ARRAY['cura']::text[], NULL, NULL, 0.25, '500 PO'),
  (403, 'Poção de Cura Superior', 'Restaura 10d4+20 pontos de vida ao ser consumida.', ARRAY['poção','cura']::text[], '{"cura":"10d4+20"}', NULL, ARRAY[]::text[], NULL, 4, 'Elixir lendário de cor dourada, feito com sangue de dragão dourado purificado.', NULL, (SELECT id FROM categorias_equipamento WHERE nome = 'Consumíveis'), ARRAY['cura']::text[], NULL, NULL, 0.25, '2.000 PO'),
  (404, 'Poção de Cura Divina', 'Restaura todo o HP do personagem. Extremamente rara.', ARRAY['poção','cura']::text[], '{"cura":"full"}', NULL, ARRAY[]::text[], NULL, 5, 'Líquido prateado que brilha com luz própria. Abençoada pelos deuses da vida.', NULL, (SELECT id FROM categorias_equipamento WHERE nome = 'Consumíveis'), ARRAY['cura']::text[], NULL, NULL, 0.25, '10.000 PO'),
  (405, 'Poção de Regeneração', 'Regenera 1 HP por turno durante 10 turnos.', ARRAY['poção','cura','regeneração']::text[], '{"regeneracao":{"hp_por_turno":1,"duracao":10}}', NULL, ARRAY[]::text[], NULL, 3, 'Líquido verde-esmeralda com partículas douradas em suspensão.', NULL, (SELECT id FROM categorias_equipamento WHERE nome = 'Consumíveis'), ARRAY['cura']::text[], NULL, NULL, 0.25, '400 PO'),
  (406, 'Elixir de Vitalidade', 'Restaura 4d4+4 HP e remove efeitos de veneno.', ARRAY['poção','cura','antídoto']::text[], '{"cura":"4d4+4","remove_status":["envenenado"]}', NULL, ARRAY[]::text[], NULL, 2, 'Mistura azul-turquesa feita com raiz de mandrágora e mel de abelhas sagradas.', NULL, (SELECT id FROM categorias_equipamento WHERE nome = 'Consumíveis'), ARRAY['cura']::text[], NULL, NULL, 0.3, '200 PO'),
  (407, 'Poção de Restauração Menor', 'Remove um efeito de status negativo (exceto maldição).', ARRAY['poção','restauração']::text[], '{"remove_status":["envenenado","cego","surdo","paralizado"]}', NULL, ARRAY[]::text[], NULL, 2, 'Líquido cristalino com reflexos iridescentes, destilado com orvalho matinal abençoado.', NULL, (SELECT id FROM categorias_equipamento WHERE nome = 'Consumíveis'), ARRAY['cura']::text[], NULL, NULL, 0.25, '120 PO'),
  (408, 'Poção de Restauração Maior', 'Remove todos os efeitos de status negativos e restaura 2d4 HP.', ARRAY['poção','restauração']::text[], '{"cura":"2d4","remove_status":"todos"}', NULL, ARRAY[]::text[], NULL, 4, 'Elixir branco-perolado que emana calor suave. Feito com penas de anjo dissolvidas.', NULL, (SELECT id FROM categorias_equipamento WHERE nome = 'Consumíveis'), ARRAY['cura']::text[], NULL, NULL, 0.25, '1.500 PO'),
  (409, 'Frasco de Vida', 'Quando HP chega a 0, restaura automaticamente 3d4 HP. Consumido ao ativar.', ARRAY['poção','cura','passivo']::text[], '{"cura_passiva":"3d4","trigger":"hp_zero"}', NULL, ARRAY[]::text[], NULL, 3, 'Ampola de cristal vermelho presa ao pescoço. Quebra-se magicamente ao detectar morte iminente.', NULL, (SELECT id FROM categorias_equipamento WHERE nome = 'Consumíveis'), ARRAY['cura']::text[], NULL, NULL, 0.1, '600 PO'),

