  (410, 'Poção de Força de Gigante', 'Aumenta Força em +4 por 1 hora.', ARRAY['poção','buff','força']::text[], '{"buff":{"atributo":"forca","valor":4,"duracao":"1h"}}', NULL, ARRAY[]::text[], NULL, 3, 'Líquido âmbar espesso com gosto de terra e ferro. Receita dos anões das montanhas.', NULL, (SELECT id FROM categorias_equipamento WHERE nome = 'Consumíveis'), ARRAY['buff']::text[], NULL, NULL, 0.3, '450 PO'),
  (411, 'Poção de Agilidade Felina', 'Aumenta Agilidade em +4 por 1 hora.', ARRAY['poção','buff','agilidade']::text[], '{"buff":{"atributo":"agilidade","valor":4,"duracao":"1h"}}', NULL, ARRAY[]::text[], NULL, 3, 'Líquido prateado leve como ar, extraído de ervas da floresta dos elfos.', NULL, (SELECT id FROM categorias_equipamento WHERE nome = 'Consumíveis'), ARRAY['buff']::text[], NULL, NULL, 0.2, '450 PO'),
  (412, 'Poção de Sabedoria Arcana', 'Aumenta Inteligência em +4 por 1 hora.', ARRAY['poção','buff','inteligência']::text[], '{"buff":{"atributo":"inteligencia","valor":4,"duracao":"1h"}}', NULL, ARRAY[]::text[], NULL, 3, 'Líquido azul-índigo com pequenas estrelas flutuando dentro do frasco.', NULL, (SELECT id FROM categorias_equipamento WHERE nome = 'Consumíveis'), ARRAY['buff']::text[], NULL, NULL, 0.2, '450 PO'),
  (413, 'Poção de Constituição de Urso', 'Aumenta Constituição em +4 por 1 hora, concede +8 HP temporário.', ARRAY['poção','buff','constituição']::text[], '{"buff":{"atributo":"constituicao","valor":4,"duracao":"1h"},"hp_temporario":8}', NULL, ARRAY[]::text[], NULL, 3, 'Líquido marrom-escuro viscoso com cheiro forte de musgo e madeira.', NULL, (SELECT id FROM categorias_equipamento WHERE nome = 'Consumíveis'), ARRAY['buff']::text[], NULL, NULL, 0.3, '500 PO'),
  (414, 'Poção de Carisma Encantador', 'Aumenta Carisma em +4 por 1 hora.', ARRAY['poção','buff','carisma']::text[], '{"buff":{"atributo":"carisma","valor":4,"duracao":"1h"}}', NULL, ARRAY[]::text[], NULL, 3, 'Perfume líquido rosa-dourado que faz quem bebe irradiar confiança.', NULL, (SELECT id FROM categorias_equipamento WHERE nome = 'Consumíveis'), ARRAY['buff']::text[], NULL, NULL, 0.2, '450 PO'),
  (415, 'Poção de Destreza de Serpente', 'Aumenta Destreza em +4 por 1 hora.', ARRAY['poção','buff','destreza']::text[], '{"buff":{"atributo":"destreza","valor":4,"duracao":"1h"}}', NULL, ARRAY[]::text[], NULL, 3, 'Líquido verde-limão translúcido com reflexos de escamas.', NULL, (SELECT id FROM categorias_equipamento WHERE nome = 'Consumíveis'), ARRAY['buff']::text[], NULL, NULL, 0.2, '450 PO'),
  (416, 'Poção de Heroísmo', 'Concede +2 em ataque e dano por 3 combates.', ARRAY['poção','buff','combate']::text[], '{"buff":{"ataque":2,"dano":2,"duracao":"3 combates"}}', NULL, ARRAY[]::text[], NULL, 2, 'Líquido dourado efervescente que faz o coração bater com coragem sobrenatural.', NULL, (SELECT id FROM categorias_equipamento WHERE nome = 'Consumíveis'), ARRAY['buff']::text[], NULL, NULL, 0.25, '250 PO'),
  (417, 'Poção de Velocidade', 'Concede uma ação extra por 3 turnos de combate.', ARRAY['poção','buff','velocidade']::text[], '{"buff":{"acao_extra":true,"duracao":"3 turnos"}}', NULL, ARRAY[]::text[], NULL, 4, 'Líquido amarelo-elétrico que parece vibrar no frasco. Derivado de essência de relâmpago.', NULL, (SELECT id FROM categorias_equipamento WHERE nome = 'Consumíveis'), ARRAY['buff']::text[], NULL, NULL, 0.2, '1.200 PO'),
  (418, 'Poção de Invisibilidade', 'Torna invisível por 1 hora ou até atacar.', ARRAY['poção','buff','invisibilidade']::text[], '{"buff":{"invisibilidade":true,"duracao":"1h","quebra_ao_atacar":true}}', NULL, ARRAY[]::text[], NULL, 4, 'Líquido perfeitamente transparente — só visível pelo brilho do frasco.', NULL, (SELECT id FROM categorias_equipamento WHERE nome = 'Consumíveis'), ARRAY['buff']::text[], NULL, NULL, 0.2, '1.500 PO'),
  (419, 'Poção de Voo', 'Permite voar por 1 hora.', ARRAY['poção','buff','voo']::text[], '{"buff":{"voo":true,"duracao":"1h"}}', NULL, ARRAY[]::text[], NULL, 4, 'Líquido branco como nuvem que flutua dentro do frasco.', NULL, (SELECT id FROM categorias_equipamento WHERE nome = 'Consumíveis'), ARRAY['buff']::text[], NULL, NULL, 0.2, '1.800 PO'),
  (420, 'Poção de Resistência ao Fogo', 'Concede resistência a dano de fogo por 1 hora.', ARRAY['poção','buff','resistência']::text[], '{"buff":{"resistencia":"fogo","duracao":"1h"}}', NULL, ARRAY['fogo']::text[], NULL, 2, 'Líquido laranja-avermelhado que emana calor suave.', NULL, (SELECT id FROM categorias_equipamento WHERE nome = 'Consumíveis'), ARRAY['resistencia']::text[], NULL, NULL, 0.25, '200 PO'),
  (421, 'Poção de Resistência ao Gelo', 'Concede resistência a dano de gelo por 1 hora.', ARRAY['poção','buff','resistência']::text[], '{"buff":{"resistencia":"gelo","duracao":"1h"}}', NULL, ARRAY['gelo']::text[], NULL, 2, 'Líquido azul-glacial com cristais de gelo flutuando dentro.', NULL, (SELECT id FROM categorias_equipamento WHERE nome = 'Consumíveis'), ARRAY['resistencia']::text[], NULL, NULL, 0.25, '200 PO'),
  (422, 'Poção de Resistência a Veneno', 'Concede imunidade a veneno por 1 hora.', ARRAY['poção','buff','resistência']::text[], '{"buff":{"imunidade":"veneno","duracao":"1h"}}', NULL, ARRAY['veneno']::text[], NULL, 2, 'Líquido verde-oliva amargo com cheiro de hortelã.', NULL, (SELECT id FROM categorias_equipamento WHERE nome = 'Consumíveis'), ARRAY['resistencia']::text[], NULL, NULL, 0.25, '250 PO'),
  (423, 'Poção de Resistência Elétrica', 'Concede resistência a dano elétrico por 1 hora.', ARRAY['poção','buff','resistência']::text[], '{"buff":{"resistencia":"relampago","duracao":"1h"}}', NULL, ARRAY['relampago']::text[], NULL, 2, 'Líquido amarelo cintilante que produz pequenas faíscas.', NULL, (SELECT id FROM categorias_equipamento WHERE nome = 'Consumíveis'), ARRAY['resistencia']::text[], NULL, NULL, 0.25, '200 PO'),
  (424, 'Poção de Armadura Mágica', 'Concede +3 de armadura por 1 hora.', ARRAY['poção','buff','defesa']::text[], '{"buff":{"armadura":3,"duracao":"1h"}}', NULL, ARRAY[]::text[], NULL, 2, 'Líquido cinza-metálico que endurece a pele temporariamente como aço.', NULL, (SELECT id FROM categorias_equipamento WHERE nome = 'Consumíveis'), ARRAY['buff']::text[], NULL, NULL, 0.3, '300 PO'),

-- ===================== VENENOS (25-35) =====================
  (425, 'Veneno Básico', 'Aplica 1d4 dano de veneno por 3 turnos ao alvo atingido.', ARRAY['veneno','ofensivo']::text[], '{"dano_por_turno":"1d4","elemento":"veneno","duracao":3}', NULL, ARRAY['veneno']::text[], NULL, 1, 'Extrato de cogumelo negro diluído em álcool. Popular entre assassinos iniciantes.', NULL, (SELECT id FROM categorias_equipamento WHERE nome = 'Consumíveis'), ARRAY['ofensivo']::text[], NULL, NULL, 0.1, '25 PO'),
  (426, 'Veneno de Víbora', 'Aplica 2d4 dano de veneno por 3 turnos.', ARRAY['veneno','ofensivo']::text[], '{"dano_por_turno":"2d4","elemento":"veneno","duracao":3}', NULL, ARRAY['veneno']::text[], NULL, 2, 'Veneno extraído de víboras das cavernas profundas, concentrado e purificado.', NULL, (SELECT id FROM categorias_equipamento WHERE nome = 'Consumíveis'), ARRAY['ofensivo']::text[], NULL, NULL, 0.1, '100 PO'),
  (427, 'Veneno de Wyvern', 'Aplica 3d4 dano de veneno por 5 turnos.', ARRAY['veneno','ofensivo']::text[], '{"dano_por_turno":"3d4","elemento":"veneno","duracao":5}', NULL, ARRAY['veneno']::text[], NULL, 3, 'Veneno letal extraído das presas de wyverns selvagens. Extremamente potente.', NULL, (SELECT id FROM categorias_equipamento WHERE nome = 'Consumíveis'), ARRAY['ofensivo']::text[], NULL, NULL, 0.1, '500 PO'),
  (428, 'Veneno Paralisante', 'Chance de 50% de paralisar o alvo por 2 turnos.', ARRAY['veneno','ofensivo','controle']::text[], '{"status":"paralizado","chance":0.5,"duracao":2}', NULL, ARRAY['veneno']::text[], NULL, 2, 'Composto raro derivado de rãs tropicais e esporos de fungo paralisante.', NULL, (SELECT id FROM categorias_equipamento WHERE nome = 'Consumíveis'), ARRAY['ofensivo']::text[], NULL, NULL, 0.1, '150 PO'),
  (429, 'Veneno Sonífero', 'Chance de 60% de adormecer o alvo por 3 turnos.', ARRAY['veneno','ofensivo','controle']::text[], '{"status":"adormecido","chance":0.6,"duracao":3}', NULL, ARRAY['veneno']::text[], NULL, 2, 'Extrato de papoula sombria misturado com pó de fada.', NULL, (SELECT id FROM categorias_equipamento WHERE nome = 'Consumíveis'), ARRAY['ofensivo']::text[], NULL, NULL, 0.1, '120 PO'),
  (430, 'Veneno de Dragão Negro', 'Aplica 4d6 dano de ácido por 3 turnos.', ARRAY['veneno','ofensivo']::text[], '{"dano_por_turno":"4d6","elemento":"acido","duracao":3}', NULL, ARRAY['acido']::text[], NULL, 4, 'Ácido concentrado extraído das glândulas de um dragão negro. Letal e corrosivo.', NULL, (SELECT id FROM categorias_equipamento WHERE nome = 'Consumíveis'), ARRAY['ofensivo']::text[], NULL, NULL, 0.1, '2.000 PO'),
  (431, 'Antídoto Universal', 'Remove qualquer efeito de veneno instantaneamente.', ARRAY['antídoto','cura']::text[], '{"remove_status":["envenenado"]}', NULL, ARRAY[]::text[], NULL, 1, 'Pasta verde-clara feita com ervas curativas universais. Todo aventureiro deveria carregar uma.', NULL, (SELECT id FROM categorias_equipamento WHERE nome = 'Consumíveis'), ARRAY['cura']::text[], NULL, NULL, 0.1, '50 PO'),
  (432, 'Óleo Venenoso', 'Aplica veneno à arma: próximo ataque causa +2d6 dano de veneno.', ARRAY['óleo','veneno','ofensivo']::text[], '{"dano_extra":"2d6","elemento":"veneno","duracao":"1 ataque"}', NULL, ARRAY['veneno']::text[], NULL, 2, 'Óleo viscoso verde-escuro para aplicar em lâminas. Um único golpe bastará.', NULL, (SELECT id FROM categorias_equipamento WHERE nome = 'Consumíveis'), ARRAY['ofensivo']::text[], NULL, NULL, 0.1, '100 PO'),

