  (435, 'Bomba de Ácido', 'Arremessável. Causa 2d8 dano de ácido e reduz armadura em 1 por 3 turnos.', ARRAY['bomba','arremessável','ofensivo']::text[], '{"debuff":{"armadura":-1,"duracao":3}}', '2d8', ARRAY['acido']::text[], NULL, 2, 'Frasco de cerâmica com ácido concentrado de gelatinous cube.', NULL, (SELECT id FROM categorias_equipamento WHERE nome = 'Consumíveis'), ARRAY['arremessavel','area']::text[], NULL, NULL, 0.5, '175 PO'),
  (436, 'Bomba de Relâmpago', 'Arremessável. Causa 3d6 dano elétrico e chance de atordoar por 1 turno.', ARRAY['bomba','arremessável','ofensivo']::text[], '{"status":"atordoado","chance":0.3,"duracao":1}', '3d6', ARRAY['relampago']::text[], NULL, 3, 'Esfera de metal com um núcleo de essência de tempestade capturada.', NULL, (SELECT id FROM categorias_equipamento WHERE nome = 'Consumíveis'), ARRAY['arremessavel','area']::text[], NULL, NULL, 0.5, '350 PO'),
  (437, 'Bomba de Fumaça', 'Cria nuvem de fumaça (5m raio) por 3 turnos. Obscurece visão.', ARRAY['bomba','arremessável','utilidade']::text[], '{"status":"cego","area":"5m","duracao":3}', NULL, ARRAY[]::text[], NULL, 1, 'Bolsa de pólvora especial que produz fumaça densa ao impacto.', NULL, (SELECT id FROM categorias_equipamento WHERE nome = 'Consumíveis'), ARRAY['arremessavel','area']::text[], NULL, NULL, 0.3, '30 PO'),
  (438, 'Bomba de Luz Sagrada', 'Arremessável. Causa 4d6 dano radiante a mortos-vivos. 2d6 a outros.', ARRAY['bomba','arremessável','ofensivo']::text[], NULL, '4d6', ARRAY['radiante']::text[], NULL, 2, 'Frasco de água benta cristalizada com fragmento de luz solar capturada.', NULL, (SELECT id FROM categorias_equipamento WHERE nome = 'Consumíveis'), ARRAY['arremessavel','area']::text[], NULL, NULL, 0.3, '200 PO'),
  (439, 'Bomba Necrótica', 'Arremessável. Causa 3d8 dano necrótico e drena 1d4 HP para o lançador.', ARRAY['bomba','arremessável','ofensivo']::text[], '{"dreno":"1d4"}', '3d8', ARRAY['necrotico']::text[], NULL, 3, 'Esfera de obsidiana contendo essência do plano das sombras.', NULL, (SELECT id FROM categorias_equipamento WHERE nome = 'Consumíveis'), ARRAY['arremessavel','area']::text[], NULL, NULL, 0.4, '400 PO'),
  (440, 'Bomba de Cola Alquímica', 'Arremessável. Prende alvos na área por 2 turnos.', ARRAY['bomba','arremessável','controle']::text[], '{"status":"preso","area":"3m","duracao":2}', NULL, ARRAY[]::text[], NULL, 1, 'Frasco com substância pegajosa que se expande ao contato com ar.', NULL, (SELECT id FROM categorias_equipamento WHERE nome = 'Consumíveis'), ARRAY['arremessavel','area']::text[], NULL, NULL, 0.5, '40 PO'),
  (441, 'Bomba Sônica', 'Arremessável. Causa 2d6 dano de trovão e ensurdece por 2 turnos.', ARRAY['bomba','arremessável','ofensivo']::text[], '{"status":"surdo","duracao":2}', '2d6', ARRAY['trovao']::text[], NULL, 2, 'Esfera de bronze contendo ar comprimido a pressões impossíveis.', NULL, (SELECT id FROM categorias_equipamento WHERE nome = 'Consumíveis'), ARRAY['arremessavel','area']::text[], NULL, NULL, 0.4, '175 PO'),
  (442, 'Fogo Alquímico', 'Arremessável. Causa 1d6 dano de fogo por 3 turnos (queimando).', ARRAY['bomba','arremessável','ofensivo']::text[], '{"status":"queimando","dano_por_turno":"1d6","duracao":3}', '1d6', ARRAY['fogo']::text[], NULL, 1, 'O clássico fogo alquímico — arde mesmo debaixo d''água.', NULL, (SELECT id FROM categorias_equipamento WHERE nome = 'Consumíveis'), ARRAY['arremessavel']::text[], NULL, NULL, 0.5, '25 PO'),
