  (446, 'Óleo Elétrico', 'Reveste arma com eletricidade: +1d6 dano elétrico por 3 ataques.', ARRAY['óleo','buff','ofensivo']::text[], '{"dano_extra":"1d6","elemento":"relampago","duracao":"3 ataques"}', NULL, ARRAY['relampago']::text[], NULL, 1, 'Óleo amarelo cintilante que faz armas crepitarem com faíscas.', NULL, (SELECT id FROM categorias_equipamento WHERE nome = 'Consumíveis'), ARRAY['buff']::text[], NULL, NULL, 0.2, '50 PO'),
