  (448, 'Óleo de Afiação', 'Reveste arma: +2 em jogadas de dano por 5 ataques.', ARRAY['óleo','buff']::text[], '{"buff":{"dano":2,"duracao":"5 ataques"}}', NULL, ARRAY[]::text[], NULL, 1, 'Óleo metálico que afina molecularmente o fio de qualquer lâmina.', NULL, (SELECT id FROM categorias_equipamento WHERE nome = 'Consumíveis'), ARRAY['buff']::text[], NULL, NULL, 0.2, '60 PO'),
  (449, 'Óleo de Precisão', 'Reveste arma: +2 em jogadas de ataque por 5 ataques.', ARRAY['óleo','buff']::text[], '{"buff":{"ataque":2,"duracao":"5 ataques"}}', NULL, ARRAY[]::text[], NULL, 1, 'Óleo mágico que guia a arma em direção a pontos vitais do alvo.', NULL, (SELECT id FROM categorias_equipamento WHERE nome = 'Consumíveis'), ARRAY['buff']::text[], NULL, NULL, 0.2, '60 PO'),
  (450, 'Óleo Antiferrugem', 'Protege armadura: +1 armadura por 24 horas.', ARRAY['óleo','buff','defesa']::text[], '{"buff":{"armadura":1,"duracao":"24h"}}', NULL, ARRAY[]::text[], NULL, 1, 'Óleo cinza-prateado que cria uma película protetora sobre metal.', NULL, (SELECT id FROM categorias_equipamento WHERE nome = 'Consumíveis'), ARRAY['buff']::text[], NULL, NULL, 0.3, '30 PO'),
  (451, 'Óleo da Escuridão', 'Reveste arma com energia necrótica: +1d8 dano necrótico por 3 ataques.', ARRAY['óleo','buff','ofensivo']::text[], '{"dano_extra":"1d8","elemento":"necrotico","duracao":"3 ataques"}', NULL, ARRAY['necrotico']::text[], NULL, 2, 'Óleo negro como a noite que absorve luz ao redor da lâmina.', NULL, (SELECT id FROM categorias_equipamento WHERE nome = 'Consumíveis'), ARRAY['buff']::text[], NULL, NULL, 0.2, '120 PO'),
