  (457, 'Pergaminho de Proteção contra Mortos-Vivos', 'Uso único. Cria barreira contra mortos-vivos por 10 minutos.', ARRAY['pergaminho','magia','defesa']::text[], '{"efeito":"barreira","alvo":"mortos-vivos","duracao":"10min"}', NULL, ARRAY['radiante']::text[], NULL, 2, 'Pergaminho com selos sagrados que repelem a não-morte.', NULL, (SELECT id FROM categorias_equipamento WHERE nome = 'Consumíveis'), ARRAY['magia','defesa']::text[], NULL, NULL, 0.05, '200 PO'),
