  (459, 'Pergaminho de Reviver', 'Uso único. Revive um aliado derrotado com 1 HP.', ARRAY['pergaminho','magia','cura']::text[], '{"efeito":"reviver","hp_restaurado":1}', NULL, ARRAY[]::text[], NULL, 4, 'Pergaminho sagrado extremamente raro com runas de ressurreição.', NULL, (SELECT id FROM categorias_equipamento WHERE nome = 'Consumíveis'), ARRAY['magia','cura']::text[], NULL, NULL, 0.05, '3.000 PO'),
  (460, 'Pergaminho de Escudo Mágico', 'Uso único. Concede +5 armadura ao alvo por 3 turnos.', ARRAY['pergaminho','magia','defesa']::text[], '{"buff":{"armadura":5,"duracao":"3 turnos"}}', NULL, ARRAY[]::text[], NULL, 2, 'Pergaminho com runas de abjuração que criam uma barreira de força.', NULL, (SELECT id FROM categorias_equipamento WHERE nome = 'Consumíveis'), ARRAY['magia','defesa']::text[], NULL, NULL, 0.05, '200 PO'),
