  (462, 'Pergaminho de Invocar Elemental', 'Uso único. Invoca um elemental aliado por 5 turnos.', ARRAY['pergaminho','magia','invocação']::text[], '{"efeito":"invocar","criatura":"elemental","duracao":"5 turnos"}', NULL, ARRAY[]::text[], NULL, 4, 'Pergaminho com runas planares que rasgam brevemente o véu entre planos.', NULL, (SELECT id FROM categorias_equipamento WHERE nome = 'Consumíveis'), ARRAY['magia','invocacao']::text[], NULL, NULL, 0.05, '2.000 PO'),
  (463, 'Pergaminho de Silêncio', 'Uso único. Cria zona de silêncio (5m) por 5 turnos. Impede magias.', ARRAY['pergaminho','magia','controle']::text[], '{"efeito":"silencio","area":"5m","duracao":"5 turnos"}', NULL, ARRAY[]::text[], NULL, 2, 'Pergaminho com runas que absorvem ondas sonoras numa área.', NULL, (SELECT id FROM categorias_equipamento WHERE nome = 'Consumíveis'), ARRAY['magia','controle']::text[], NULL, NULL, 0.05, '200 PO'),
  (464, 'Pergaminho de Maldição', 'Uso único. Aplica -2 em todos os atributos do alvo por 1 hora.', ARRAY['pergaminho','magia','ofensivo']::text[], '{"debuff":{"todos_atributos":-2,"duracao":"1h"}}', NULL, ARRAY['necrotico']::text[], NULL, 3, 'Pergaminho sombrio com runas escritas em sangue seco.', NULL, (SELECT id FROM categorias_equipamento WHERE nome = 'Consumíveis'), ARRAY['magia','ofensivo']::text[], NULL, NULL, 0.05, '400 PO'),
