  (466, 'Erva Curativa', 'Pode ser aplicada em ferimentos. Restaura 1d4 HP.', ARRAY['erva','cura']::text[], '{"cura":"1d4"}', NULL, ARRAY[]::text[], NULL, 1, 'Folha verde-escura com propriedades medicinais. Encontrada em florestas temperadas.', NULL, (SELECT id FROM categorias_equipamento WHERE nome = 'Consumíveis'), ARRAY['cura']::text[], NULL, NULL, 0.05, '5 PO'),
  (467, 'Raiz de Mandrágora', 'Remove efeito de atordoamento ou paralisia.', ARRAY['erva','cura','restauração']::text[], '{"remove_status":["atordoado","paralizado"]}', NULL, ARRAY[]::text[], NULL, 2, 'Raiz retorcida em forma humanoide que grita ao ser arrancada. Manipular com cuidado.', NULL, (SELECT id FROM categorias_equipamento WHERE nome = 'Consumíveis'), ARRAY['cura']::text[], NULL, NULL, 0.1, '75 PO'),
