  (469, 'Cogumelo Luminescente', 'Emite luz fraca (3m) por 8 horas ao ser ativado.', ARRAY['erva','utilidade']::text[], '{"efeito":"luz","raio":"3m","duracao":"8h"}', NULL, ARRAY[]::text[], NULL, 1, 'Cogumelo azul-brilhante das cavernas profundas. Alternativa barata a tochas.', NULL, (SELECT id FROM categorias_equipamento WHERE nome = 'Consumíveis'), ARRAY['utilidade']::text[], NULL, NULL, 0.05, '2 PO'),
