  (472, 'Musgo Regenerativo', 'Quando aplicado, regenera 1 HP por turno por 5 turnos.', ARRAY['erva','cura','regeneração']::text[], '{"regeneracao":{"hp_por_turno":1,"duracao":5}}', NULL, ARRAY[]::text[], NULL, 1, 'Musgo esverdeado que pulsa suavemente. Cresce em ruínas élficas antigas.', NULL, (SELECT id FROM categorias_equipamento WHERE nome = 'Consumíveis'), ARRAY['cura']::text[], NULL, NULL, 0.05, '15 PO'),
