  (480, 'Fruta do Dragão', 'Concede resistência ao elemento do dragão correspondente por 1 hora.', ARRAY['alimento','buff','resistência']::text[], '{"buff":{"resistencia":"variavel","duracao":"1h"}}', NULL, ARRAY[]::text[], NULL, 3, 'Fruta exótica que cresce apenas em ninhos de dragões abandonados. Cada cor confere resistência diferente.', NULL, (SELECT id FROM categorias_equipamento WHERE nome = 'Consumíveis'), ARRAY['resistencia']::text[], NULL, NULL, 0.2, '250 PO'),
