  (496, 'Tinta Invisível', 'Escreve mensagens que só aparecem com calor ou magia. 10 usos.', ARRAY['utilidade','espionagem']::text[], '{"efeito":"escrita_invisivel"}', NULL, ARRAY[]::text[], NULL, 1, 'Tinta feita com tinta de lula gigante e ervas alquímicas. Seca transparente.', NULL, (SELECT id FROM categorias_equipamento WHERE nome = 'Consumíveis'), ARRAY['utilidade']::text[], 10, NULL, 0.1, '25 PO'),
  (497, 'Sinalizador Arcano', 'Dispara luz brilhante visível a 1km. Sinalização.', ARRAY['utilidade','sinalização']::text[], '{"efeito":"sinal_luz","alcance":"1km"}', NULL, ARRAY[]::text[], NULL, 1, 'Bastão curto que dispara faísca mágica de cor escolhida ao ser partido.', NULL, (SELECT id FROM categorias_equipamento WHERE nome = 'Consumíveis'), ARRAY['utilidade']::text[], NULL, NULL, 0.1, '5 PO'),
  (498, 'Poção de Respirar na Água', 'Permite respirar debaixo d''água por 1 hora.', ARRAY['poção','buff','utilidade']::text[], '{"buff":{"respirar_agua":true,"duracao":"1h"}}', NULL, ARRAY[]::text[], NULL, 2, 'Líquido azul-marinho com pequenas bolhas perpétuas flutuando dentro.', NULL, (SELECT id FROM categorias_equipamento WHERE nome = 'Consumíveis'), ARRAY['buff']::text[], NULL, NULL, 0.25, '150 PO'),
  (499, 'Poção de Visão Noturna', 'Concede visão no escuro (18m) por 8 horas.', ARRAY['poção','buff','utilidade']::text[], '{"buff":{"visao_noturna":"18m","duracao":"8h"}}', NULL, ARRAY[]::text[], NULL, 1, 'Líquido negro com reflexos esverdeados. Olhos brilham no escuro após consumo.', NULL, (SELECT id FROM categorias_equipamento WHERE nome = 'Consumíveis'), ARRAY['buff']::text[], NULL, NULL, 0.25, '50 PO'),
  (500, 'Poção de Encolher', 'Reduz o tamanho pela metade por 1 hora. -2 Força, +2 Destreza.', ARRAY['poção','buff','transformação']::text[], '{"buff":{"forca":-2,"destreza":2,"duracao":"1h","tamanho":"metade"}}', NULL, ARRAY[]::text[], NULL, 2, 'Líquido rosa claro que borbulha intensamente ao ser aberto.', NULL, (SELECT id FROM categorias_equipamento WHERE nome = 'Consumíveis'), ARRAY['buff']::text[], NULL, NULL, 0.25, '200 PO'),
  (501, 'Poção de Crescer', 'Dobra o tamanho por 1 hora. +2 Força, -2 Destreza.', ARRAY['poção','buff','transformação']::text[], '{"buff":{"forca":2,"destreza":-2,"duracao":"1h","tamanho":"dobro"}}', NULL, ARRAY[]::text[], NULL, 2, 'Líquido vermelho que expande ao contato com ar.', NULL, (SELECT id FROM categorias_equipamento WHERE nome = 'Consumíveis'), ARRAY['buff']::text[], NULL, NULL, 0.25, '200 PO'),
  (502, 'Elixir de Sorte', 'Concede vantagem no próximo teste (rola duas vezes, usa o maior).', ARRAY['poção','buff']::text[], '{"buff":{"vantagem_proximo_teste":true}}', NULL, ARRAY[]::text[], NULL, 3, 'Líquido dourado com trevos de quatro folhas em suspensão.', NULL, (SELECT id FROM categorias_equipamento WHERE nome = 'Consumíveis'), ARRAY['buff']::text[], NULL, NULL, 0.2, '350 PO'),
  (503, 'Poção de Linguagens', 'Permite entender e falar qualquer idioma por 1 hora.', ARRAY['poção','buff','utilidade']::text[], '{"buff":{"compreender_idiomas":true,"duracao":"1h"}}', NULL, ARRAY[]::text[], NULL, 2, 'Líquido multicolorido que muda de sabor a cada gole.', NULL, (SELECT id FROM categorias_equipamento WHERE nome = 'Consumíveis'), ARRAY['buff']::text[], NULL, NULL, 0.25, '150 PO'),
  (504, 'Poção de Forma Gasosa', 'Transforma o corpo em névoa por 1 hora. Pode passar por frestas.', ARRAY['poção','buff','transformação']::text[], '{"buff":{"forma_gasosa":true,"duracao":"1h"}}', NULL, ARRAY[]::text[], NULL, 3, 'Líquido cinza que evapora parcialmente no frasco.', NULL, (SELECT id FROM categorias_equipamento WHERE nome = 'Consumíveis'), ARRAY['buff']::text[], NULL, NULL, 0.25, '400 PO'),
  (505, 'Poção de Escalada de Aranha', 'Permite escalar qualquer superfície por 1 hora.', ARRAY['poção','buff','utilidade']::text[], '{"buff":{"escalada_aranha":true,"duracao":"1h"}}', NULL, ARRAY[]::text[], NULL, 2, 'Líquido cinza pegajoso que gruda nos dedos após consumo.', NULL, (SELECT id FROM categorias_equipamento WHERE nome = 'Consumíveis'), ARRAY['buff']::text[], NULL, NULL, 0.25, '150 PO'),
  (506, 'Poção de Mente Limpa', 'Remove efeitos de charme, medo e confusão.', ARRAY['poção','restauração']::text[], '{"remove_status":["enfeiticado","amedrontado","confuso"]}', NULL, ARRAY[]::text[], NULL, 2, 'Líquido cristalino com aroma de menta que limpa a mente instantaneamente.', NULL, (SELECT id FROM categorias_equipamento WHERE nome = 'Consumíveis'), ARRAY['cura']::text[], NULL, NULL, 0.25, '120 PO'),
  (507, 'Kit de Armadilhas', 'Permite montar armadilhas simples em campo. 3 armadilhas.', ARRAY['kit','utilidade','combate']::text[], '{"efeito":"montar_armadilha","dano":"2d6","quantidade":3}', NULL, ARRAY[]::text[], NULL, 1, 'Estojo com arame, pregos, molas e mecanismos de disparo compactos.', NULL, (SELECT id FROM categorias_equipamento WHERE nome = 'Consumíveis'), ARRAY['utilidade']::text[], 3, NULL, 2.0, '50 PO'),
  (508, 'Pó de Rastreamento', 'Marca uma criatura. Pode ser rastreada por 24 horas.', ARRAY['pó','utilidade','espionagem']::text[], '{"efeito":"rastrear","duracao":"24h"}', NULL, ARRAY[]::text[], NULL, 2, 'Pó dourado quase invisível que gruda em qualquer superfície.', NULL, (SELECT id FROM categorias_equipamento WHERE nome = 'Consumíveis'), ARRAY['utilidade']::text[], NULL, NULL, 0.05, '75 PO'),
  (509, 'Ampola de Cura de Emergência', 'Injeta automaticamente: +2d4 HP quando HP cai abaixo de 5.', ARRAY['kit','cura','passivo']::text[], '{"cura_passiva":"2d4","trigger":"hp_below_5"}', NULL, ARRAY[]::text[], NULL, 2, 'Ampola gnômica com agulha retrátil que se ativa por detecção de ferimentos.', NULL, (SELECT id FROM categorias_equipamento WHERE nome = 'Consumíveis'), ARRAY['cura']::text[], NULL, NULL, 0.1, '200 PO'),
  (510, 'Pergaminho de Mapa Mágico', 'Revela a planta de um andar de dungeon.', ARRAY['pergaminho','utilidade']::text[], '{"efeito":"revelar_mapa","area":"1 andar"}', NULL, ARRAY[]::text[], NULL, 2, 'Pergaminho que desenha automaticamente o layout ao redor ao ser aberto.', NULL, (SELECT id FROM categorias_equipamento WHERE nome = 'Consumíveis'), ARRAY['utilidade']::text[], NULL, NULL, 0.05, '100 PO'),
  (511, 'Bomba de Purificação', 'Limpa área de venenos, doenças e maldições ambientais (5m).', ARRAY['bomba','utilidade','cura']::text[], '{"efeito":"purificar_area","raio":"5m"}', NULL, ARRAY['radiante']::text[], NULL, 2, 'Esfera de cristal branco que se desfaz em luz purificadora.', NULL, (SELECT id FROM categorias_equipamento WHERE nome = 'Consumíveis'), ARRAY['cura','area']::text[], NULL, NULL, 0.3, '175 PO'),
  (512, 'Elixir da Juventude', 'Efeito cosmético: rejuvenesce aparência em 10 anos. Não altera stats.', ARRAY['poção','utilidade']::text[], '{"efeito":"cosmetico","rejuvenescimento":"10 anos"}', NULL, ARRAY[]::text[], NULL, 4, 'Líquido rosado cintilante que emana vitalidade. Muito procurado por nobres.', NULL, (SELECT id FROM categorias_equipamento WHERE nome = 'Consumíveis'), ARRAY[]::text[], NULL, NULL, 0.25, '5.000 PO'),
  (513, 'Tônico de Resistência', 'Concede +2 em todas as defesas por 3 turnos.', ARRAY['poção','buff','defesa']::text[], '{"buff":{"armadura":2,"esquiva_bonus":2,"duracao":"3 turnos"}}', NULL, ARRAY[]::text[], NULL, 2, 'Líquido acobreado espesso que endurece temporariamente músculos e reflexos.', NULL, (SELECT id FROM categorias_equipamento WHERE nome = 'Consumíveis'), ARRAY['buff','defesa']::text[], NULL, NULL, 0.25, '175 PO'),
  (514, 'Pergaminho de Barreira Elemental', 'Cria barreira que absorve 20 dano elemental. Escolha elemento ao usar.', ARRAY['pergaminho','magia','defesa']::text[], '{"efeito":"barreira_elemental","absorve":20}', NULL, ARRAY[]::text[], NULL, 3, 'Pergaminho com quatro selos elementais. Rasgue um para ativar.', NULL, (SELECT id FROM categorias_equipamento WHERE nome = 'Consumíveis'), ARRAY['magia','defesa']::text[], NULL, NULL, 0.05, '300 PO'),
  (515, 'Kit de Reparação de Armadura', 'Restaura armadura danificada: +1 armadura permanente (até original). 3 usos.', ARRAY['kit','utilidade']::text[], '{"efeito":"reparar_armadura","valor":1}', NULL, ARRAY[]::text[], NULL, 1, 'Estojo com martelo pequeno, rebites, placas de reposição e fios de mithral.', NULL, (SELECT id FROM categorias_equipamento WHERE nome = 'Consumíveis'), ARRAY['utilidade']::text[], 3, NULL, 1.5, '30 PO'),
  (516, 'Elixir de Fúria', 'Concede +3 dano e -1 armadura por 5 turnos. Berserker em frasco.', ARRAY['poção','buff','combate']::text[], '{"buff":{"dano":3,"armadura":-1,"duracao":"5 turnos"}}', NULL, ARRAY[]::text[], NULL, 2, 'Líquido vermelho-sangue que faz o coração acelerar violentamente.', NULL, (SELECT id FROM categorias_equipamento WHERE nome = 'Consumíveis'), ARRAY['buff']::text[], NULL, NULL, 0.25, '200 PO'),
  (517, 'Poção de Reflexos Rápidos', 'Concede +3 esquiva por 5 turnos.', ARRAY['poção','buff','defesa']::text[], '{"buff":{"esquiva_bonus":3,"duracao":"5 turnos"}}', NULL, ARRAY[]::text[], NULL, 2, 'Líquido prateado efervescente que aguça reflexos a níveis sobre-humanos.', NULL, (SELECT id FROM categorias_equipamento WHERE nome = 'Consumíveis'), ARRAY['buff']::text[], NULL, NULL, 0.25, '200 PO'),
  (518, 'Bomba de Esporos', 'Arremessável. Aplica envenenado a todos na área (3m) por 3 turnos.', ARRAY['bomba','arremessável','ofensivo']::text[], '{"status":"envenenado","area":"3m","duracao":3}', NULL, ARRAY['veneno']::text[], NULL, 2, 'Saco de esporos de fungo venenoso comprimidos. Explode em nuvem tóxica.', NULL, (SELECT id FROM categorias_equipamento WHERE nome = 'Consumíveis'), ARRAY['arremessavel','area']::text[], NULL, NULL, 0.3, '100 PO'),
